/*
 * prog24_query_string_parser.c
 *
 * Reads a single line from stdin (up to 2047 characters), interprets it as a
 * URL‑encoded query string, decodes each key/value pair and prints them in the
 * form “key=value”.  If no line is supplied, the program prints “NO_INPUT”.
 *
 * The behaviour matches the original binary (see the decompiled `main` and
 * `decode` functions).
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX 2048          /* size of the input buffer */
#define KV_MAX   1024          /* size for a decoded key or value */

/* --------------------------------------------------------------------- */
/* Decode a URL‑encoded fragment.
 *
 *  src   – pointer to the encoded data
 *  len   – length of the encoded data
 *  dst   – buffer where the decoded string is written (null‑terminated)
 *
 * The decoder implements the standard rules:
 *   '+'  -> space
 *   "%XY" where X and Y are hex digits -> the byte with value 0xXY
 *   any other character is copied unchanged.
 * --------------------------------------------------------------------- */
static void decode(const char *src, size_t len, char *dst)
{
    size_t i = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            *dst++ = ' ';
            i++;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            int hi = isdigit((unsigned char)src[i + 1]) ?
                     src[i + 1] - '0' :
                     (tolower((unsigned char)src[i + 1]) - 'a' + 10);
            int lo = isdigit((unsigned char)src[i + 2]) ?
                     src[i + 2] - '0' :
                     (tolower((unsigned char)src[i + 2]) - 'a' + 10);
            *dst++ = (char)((hi << 4) | lo);
            i += 3;
        } else {
            *dst++ = c;
            i++;
        }
    }
    *dst = '\0';
}

/* --------------------------------------------------------------------- */
int main(void)
{
    static char line[LINE_MAX];
    static char key[KV_MAX];
    static char val[KV_MAX];

    /* Read a line from stdin. */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing CR/LF characters (the original code treats them as
       terminators). */
    size_t linelen = strlen(line);
    while (linelen && (line[linelen - 1] == '\n' || line[linelen - 1] == '\r')) {
        line[--linelen] = '\0';
    }

    /* Parse the query string: pairs are separated by '&', key/value by '='. */
    size_t pos = 0;
    while (pos < linelen) {
        size_t pair_start = pos;

        /* Find the end of the current pair. */
        while (pos < linelen && line[pos] != '&')
            pos++;
        size_t pair_end = pos;          /* one‑past the last character of the pair */

        /* Locate the first '=' inside the pair, if any. */
        size_t eq = pair_start;
        while (eq < pair_end && line[eq] != '=')
            eq++;

        /* Decode key. */
        decode(line + pair_start, eq - pair_start, key);

        /* Decode value (if present). */
        if (eq < pair_end && line[eq] == '=') {
            decode(line + eq + 1, pair_end - (eq + 1), val);
        } else {
            val[0] = '\0';
        }

        /* Output the decoded pair. */
        printf("%s=%s\n", key, val);

        /* Skip the '&' separator, if there is one, and continue with the next pair. */
        if (pos < linelen && line[pos] == '&')
            pos++;
    }

    return 0;
}
